"""Schemas shared by the four spellings (E14). `schemas.pyi` is generated by tools/tacit_gen.py."""

from datetime import date, datetime

import tacit_r as tr
from tacit_r import Column


class RawCustomer(tr.Schema):
    customer_id: Column[int]
    name: Column[str]
    email: Column[str]
    country: Column[str]
    signup_date: Column[date]


class Keyed(tr.Schema):
    """What `latest_per_key` needs: a key and a timestamp."""

    customer_id: Column[int]
    order_ts: Column[datetime]


class RawOrder(Keyed):
    order_id: Column[int]
    status: Column[str]
    amount: Column[float]
    discount: Column[float | None]


class NetAmount(tr.Schema):
    net_amount: Column[float]


class Order(RawOrder, NetAmount):
    pass


class CountryStats(tr.Schema):
    country: Column[str]
    order_count: Column[int]
    total_net: Column[float]
